let memories=[],settings={},view=new Date(),filter='Alle'; const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function init(){[memories,settings]=await Promise.all([fetch('/data/memories.json').then(r=>r.json()),fetch('/data/settings.json').then(r=>r.json())]);memories.sort((a,b)=>new Date(b.date)-new Date(a.date));document.title=settings.siteTitle||'Kanti Ziitkapsle';$('#heroLine').textContent=settings.heroLine||'';$('#footerLine').textContent=settings.footerLine||'';countdown();setInterval(countdown,30000);flashback();renderCalendar();renderCards();}
function countdown(){let d=new Date(settings.graduationDate+'T12:00:00'),n=new Date(),x=Math.max(0,d-n);$('#days').textContent=Math.floor(x/864e5);$('#hours').textContent=Math.floor(x/36e5)%24;$('#mins').textContent=Math.floor(x/6e4)%60;}
function flashback(){if(!memories.length)return;let now=new Date(),week=Math.floor((now-new Date(now.getFullYear(),0,1))/6048e5),m=memories[week%memories.length];$('#flashDay').textContent=new Date(m.date+'T12:00').getDate();$('#flashCat').textContent=m.category;$('#flashTitle').textContent=m.title;$('#flashQuote').textContent=m.quote||'';$('#flashBody').textContent=m.body;$('#flashMeta').textContent=`${fmt(m.date)} · ${m.author||'Anonym'}`;}
function renderCalendar(){let y=view.getFullYear(),mo=view.getMonth();$('#monthTitle').textContent=new Intl.DateTimeFormat('de-CH',{month:'long',year:'numeric'}).format(view);let first=new Date(y,mo,1),offset=(first.getDay()+6)%7,start=new Date(y,mo,1-offset),html='';for(let i=0;i<42;i++){let d=new Date(start);d.setDate(start.getDate()+i);let iso=localISO(d),items=memories.filter(m=>m.date===iso&&(filter==='Alle'||m.category===filter));let today=iso===localISO(new Date());html+=`<div class="day ${d.getMonth()!==mo?'muted':''} ${items.length?'has':''} ${today?'today':''}" data-date="${iso}"><b>${d.getDate()}</b>${items.slice(0,2).map(m=>`<span class="mini">${esc(m.title)}</span>`).join('')}</div>`}$('#calendar').innerHTML=html;$$('.day.has').forEach(el=>el.onclick=()=>showDay(el.dataset.date));}
function renderCards(){let list=memories.filter(m=>filter==='Alle'||m.category===filter).slice(0,9);$('#cards').innerHTML=list.map((m,i)=>`<article class="card" data-i="${memories.indexOf(m)}">${m.image?`<img src="${esc(m.image)}" alt="">`:''}<span class="tag">${esc(m.category)}</span><h3>${esc(m.title)}</h3>${m.quote?`<blockquote>“${esc(m.quote)}”</blockquote>`:''}<p>${esc(m.body).slice(0,150)}${m.body.length>150?'…':''}</p><small>${fmt(m.date)} · ${esc(m.author||'Anonym')}</small></article>`).join('')||'<p>No kei Erinnerige i dere Kategorie. Zeit, öppis z\'verewige.</p>';$$('.card').forEach(c=>c.onclick=()=>showMemory(memories[+c.dataset.i]));}
function showDay(date){let items=memories.filter(m=>m.date===date);$('#modalContent').innerHTML=`<span class="tag">${fmt(date)}</span>`+items.map(m=>`<h2>${esc(m.title)}</h2>${m.image?`<img src="${esc(m.image)}" alt="">`:''}${m.quote?`<blockquote>${esc(m.quote)}</blockquote>`:''}<p>${esc(m.body)}</p><small>${esc(m.author||'Anonym')}</small>`).join('<hr>');$('#modal').showModal();}
function showMemory(m){$('#modalContent').innerHTML=`<span class="tag">${esc(m.category)}</span><h2>${esc(m.title)}</h2>${m.image?`<img src="${esc(m.image)}" alt="">`:''}${m.quote?`<blockquote>${esc(m.quote)}</blockquote>`:''}<p>${esc(m.body)}</p><small>${fmt(m.date)} · ${esc(m.author||'Anonym')}</small>`;$('#modal').showModal();}
function fmt(d){return new Intl.DateTimeFormat('de-CH',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(d+'T12:00'))}function localISO(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
$('#prev').onclick=()=>{view.setMonth(view.getMonth()-1);renderCalendar()};$('#next').onclick=()=>{view.setMonth(view.getMonth()+1);renderCalendar()};$('#close').onclick=()=>$('#modal').close();$$('.filters button').forEach(b=>b.onclick=()=>{$$('.filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;renderCalendar();renderCards()});$('#roulette').onclick=()=>memories.length&&showMemory(memories[Math.floor(Math.random()*memories.length)]);if(window.netlifyIdentity)window.netlifyIdentity.on('init',u=>{if(!u)window.netlifyIdentity.on('login',()=>location.href='/admin/')});init();
